55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const ALIKE_ITEMS_PER_BLOCK = 3;
68	const BLOCK_BASE_PREMIUM = 60;
69	
70	const basePremiumForAlikeItems = (type: string, count: number): number =>
71	  count === ALIKE_ITEMS_PER_BLOCK
72	    ? BLOCK_BASE_PREMIUM
73	    : count * BASE_PREMIUMS[type];
74	
75	const countByType = (items: Item[]): Map<string, number> =>
76	  items.reduce(
77	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
78	    new Map<string, number>(),
79	  );
80	
81	const policyBasePremium = (items: Item[]): number =>
82	  [...countByType(items)].reduce(
83	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
84	    0,
85	  );
86	
87	const CURSE_SURCHARGE_RATE = 0.5;
88	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
89	const HIGH_ENCHANTMENT_LEVEL = 5;
90	
91	const isHighlyEnchanted = (item: Item): boolean =>
92	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
93	
94	interface RiskFactor {
95	  applies: (item: Item) => boolean;
96	  rate: number;
97	}
98	
99	const RISK_FACTORS: RiskFactor[] = [
100	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
101	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
102	];
103	
104	const itemRiskSurcharge = (item: Item): number =>
105	  RISK_FACTORS.reduce(
106	    (total, { applies, rate }) =>
107	      applies(item) ? total + BASE_PREMIUMS[item.type] * rate : total,
108	    0,
109	  );
110	
111	const totalRiskSurcharges = (items: Item[]): number =>
112	  items.reduce((total, item) => total + itemRiskSurcharge(item), 0);
113	
114	const quotePremium = (items: Item[]): number => {
115	  const policyBase = policyBasePremium(items);
116	  const riskSurcharges = totalRiskSurcharges(items);
117	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
118	  return Math.ceil(
119	    policyBase + riskSurcharges + firstInsuranceSurcharge + PROCESSING_FEE,
120	  );
121	};
122	
123	const runStep = (step: Step): StepResult => ({
124	  premium: quotePremium((step as QuoteStep).items),
125	});
126	
127	export const runScenario = (scenario: Scenario): ScenarioResult => ({
128	  results: scenario.steps.map(runStep),
129	});
